params.description:
Если "type" = "days_of_week":

1 - понедельник;
          2 - вторник;
          3 - среда;
          4 - четверг;
          5 - пятница;
          6 - суббота
          0 - воскресенье;
          8 - выходной;
          7 - рабочий;

        Если "type" = "days_of_month":

числа от 1 до 31

        Если "type" = "cycle":

Количество рабочих дней в цикле;
          Количество нерабочих дней в цикле;

        Если "type" = "business_calendar":

8 - выходной;
          7 - рабочий;

all - для всех звонков;

in - только для входящих;

out - только для исходящих;

off - отключена
